Given an array arr[] and an integer target. We want to build an expression out of arr[] by adding one of the symbols '+' and '-' before each integer in arr[] and then concatenate all the integers. Determine the number of different expressions that can be built, which evaluates to target.Example: Input : arr[] = [1, 1, 1, 1, 1], target = 3Output: 5Explanation: There are 5 ways for target 3.-1 + 1 + 1 + 1 + 1 = 3+1 - 1 + 1 + 1 + 1 = 3+1 + 1 - 1 + 1 + 1 = 3+1 + 1 + 1 - 1 + 1 = 3+1 + 1 + 1 + 1 - 1 = 3Input: arr[] = [1], target = 1Output: 1Input : arr[] = [1, 2, 2, 1], target = 2Output: 2Explanation: There are 2 ways for 21 -  2  +  2  + 11  +  2  -  2  + 1Try It Yourself[Naive Approach] Using Recursion - O(2^n) Time and O(n) Auxiliary Space The idea is to explore all possible expressions by assigning either a '+' or '-' sign to each element of the array. For every element, there are two choices: add it to the current sum or subtract it from the current sum.At each step, the current index and the cumulative sum together define the state of the recursion.When all elements have been processed, the current sum is compared with the target. If they are equal, one valid expression is found; otherwise, it is discarded.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int findPossibleWays(vector<int>& arr, int i, int s, int& target)
{

    // If target is reached, return 1
    if (s == target && i == arr.size())
        return 1;

    // If all elements are processed and
    // target is not reached, return 0
    if (i >= arr.size())
        return 0;

    // Return total count of two cases
    // 1. Add current element
    // 2. Subtract current element
    return findPossibleWays(arr, i + 1, s + arr[i], target)
           + findPossibleWays(arr, i + 1, s - arr[i], target);
}

int findTotalWays(vector<int>& arr , int target){
    return findPossibleWays(arr , 0 , 0 , target);
}

int main()
{
    vector<int> arr = { 1, 1, 1, 1, 1 };
    int target = 3;
    cout << findTotalWays(arr , target) << endl;

    return 0;
}


